-- Isolated Neon branch only; all fixture rows and the identity shim roll back.
DO $test$
DECLARE b uuid:=gen_random_uuid(); other_b uuid:=gen_random_uuid(); legacy_b uuid:=gen_random_uuid(); legacy_add_b uuid:=gen_random_uuid(); manager uuid:=gen_random_uuid(); stranger uuid:=gen_random_uuid(); newcomer uuid:=gen_random_uuid(); failed_newcomer uuid:=gen_random_uuid();
 saved public.buildings; previous public.buildings; details jsonb; finance jsonb; result jsonb; unit_id uuid; created_id uuid; denied boolean; audit_count bigint; building_count bigint;
 start_m text:=to_char(date_trunc('month',timezone('Africa/Cairo',now()))-interval '2 months','YYYY-MM');
BEGIN
 BEGIN
  EXECUTE $definition$CREATE OR REPLACE FUNCTION app_auth.user_id() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $identity$
   SELECT (nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'sub')::uuid
  $identity$$definition$;
  INSERT INTO public.buildings(id,name,balance,opening_balance) VALUES(b,'أرصدة موحدة',0,0),(other_b,'عمارة أخرى',77,77),(legacy_b,'رصيد قديم مشمول',5000,NULL),(legacy_add_b,'رصيد قديم غير مشمول',100,NULL);
  INSERT INTO app_auth.users(id,email) VALUES(manager,manager||'@example.invalid'),(stranger,stranger||'@example.invalid'),(newcomer,newcomer||'@example.invalid'),(failed_newcomer,failed_newcomer||'@example.invalid');
  UPDATE public.profiles SET role='building_admin',approved=true WHERE id IN(manager,stranger,newcomer,failed_newcomer);
  UPDATE public.profiles SET building_id=b WHERE id=manager;
  UPDATE public.profiles SET building_id=other_b WHERE id=stranger;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',manager)::text,true);
  SELECT * INTO saved FROM public.buildings WHERE id=b;
  details:=jsonb_build_object('name','أرصدة موحدة','totalUnits',2,'totalFloors',1,'monthlyTarget',2000,'reserveFund',1000);
  finance:=jsonb_build_object('baseOpening',5000,'reserve',1000,'expenses',10000,'exceptional',8000,'startMonth',start_m,'openingAlreadyIncluded',NULL,'expected',private.building_financial_snapshot(saved));
  SET LOCAL ROLE authenticated;
  result:=public.save_building_management(b,details,finance);
  IF (result->>'balance')::numeric<>3000 OR (result->>'opening_balance')::numeric<>3000 OR (result->>'reserve_fund')::numeric<>1000 THEN RAISE EXCEPTION 'Unified initial net or reserve incorrect: %',result; END IF;
  RESET ROLE;
  SELECT count(*) INTO audit_count FROM public.building_treasury_settings_audit WHERE building_id=b;
  IF audit_count<>1 OR (SELECT count(*) FROM public.apartments WHERE building_id=b)<>2 THEN RAISE EXCEPTION 'Unified save duplicated audit or unit generation'; END IF;
  denied:=false;
  BEGIN PERFORM public.save_building_management(b,details||'{"name":"تعديل مرفوض"}',finance); EXCEPTION WHEN serialization_failure THEN denied:=true; END;
  IF NOT denied OR (SELECT name FROM public.buildings WHERE id=b)<>'أرصدة موحدة' THEN RAISE EXCEPTION 'Stale snapshot was accepted or metadata partially saved'; END IF;
  SELECT * INTO saved FROM public.buildings WHERE id=b;
  finance:=finance||jsonb_build_object('expected',private.building_financial_snapshot(saved));
  PERFORM public.save_building_management(b,details,finance);
  IF (SELECT balance FROM public.buildings WHERE id=b)<>3000 OR (SELECT count(*) FROM public.building_treasury_settings_audit WHERE building_id=b)<>audit_count THEN RAISE EXCEPTION 'Repeated save duplicated opening cash or audit'; END IF;
  SELECT * INTO saved FROM public.buildings WHERE id=b;
  finance:=finance||jsonb_build_object('reserve',1500,'expected',private.building_financial_snapshot(saved));
  result:=public.save_building_management(b,details||'{"reserveFund":1500}',finance);
  IF (result->>'balance')::numeric<>3000 OR (result->>'reserve_fund')::numeric<>1500 THEN RAISE EXCEPTION 'Reserve became new collected cash'; END IF;
  SELECT id INTO unit_id FROM public.apartments WHERE building_id=b ORDER BY id LIMIT 1;
  PERFORM public.save_historical_monthly_allocations(b,jsonb_build_array(jsonb_build_object('apartmentId',unit_id,'month',start_m||'-01','amount',1000)));
  SELECT * INTO saved FROM public.buildings WHERE id=b;
  IF saved.balance<>4000 OR saved.opening_balance-saved.historical_adjustment_applied<>5000 THEN RAISE EXCEPTION 'Distribution changed base opening'; END IF;
  finance:=finance||jsonb_build_object('baseOpening',5500,'expenses',9000,'expected',private.building_financial_snapshot(saved));
  result:=public.save_building_management(b,details,finance);
  IF (result->>'balance')::numeric<>5500 OR (result->>'opening_balance')::numeric<>5500 THEN RAISE EXCEPTION 'Combined base/historical correction duplicated an adjustment'; END IF;
  result:=public.mutate_financial_entry('payment','create',b,NULL,jsonb_build_object('apartmentId',unit_id,'amount',300,'date',current_date,'month',start_m,'method','نقدي'),gen_random_uuid());
  SELECT * INTO saved FROM public.buildings WHERE id=b;
  finance:=finance||jsonb_build_object('baseOpening',5600,'expected',private.building_financial_snapshot(saved));
  result:=public.save_building_management(b,details,finance);
  IF (result->>'balance')::numeric<>5900 OR (result->>'opening_balance')::numeric<>5600 THEN RAISE EXCEPTION 'Updating base lost actual receipt cash'; END IF;
  SELECT * INTO saved FROM public.buildings WHERE id=b;
  denied:=false;
  BEGIN PERFORM public.save_building_management(b,details||'{"name":"فشل مالي"}',finance||jsonb_build_object('baseOpening',-1,'expected',private.building_financial_snapshot(saved))); EXCEPTION WHEN others THEN denied:=true; END;
  IF NOT denied OR (SELECT name FROM public.buildings WHERE id=b)<>'أرصدة موحدة' OR (SELECT balance FROM public.buildings WHERE id=b)<>5900 THEN RAISE EXCEPTION 'Financial validation left metadata or cash half saved'; END IF;
  denied:=false;
  BEGIN PERFORM public.save_building_management(b,details||'{"name":"فشل عدد الشقق","totalUnits":1}',finance||jsonb_build_object('reserve',0,'expected',private.building_financial_snapshot(saved))); EXCEPTION WHEN others THEN denied:=true; END;
  IF NOT denied OR (SELECT reserve_fund FROM public.buildings WHERE id=b)<>1500 OR (SELECT balance FROM public.buildings WHERE id=b)<>5900 THEN RAISE EXCEPTION 'Metadata failure left financial changes'; END IF;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',stranger)::text,true);
  denied:=false; BEGIN PERFORM public.save_building_management(b,details,NULL); EXCEPTION WHEN insufficient_privilege THEN denied:=true; END;
  IF NOT denied THEN RAISE EXCEPTION 'Foreign manager changed unified settings'; END IF;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',manager)::text,true);
  UPDATE public.profiles SET building_id=legacy_b WHERE id=manager;
  SELECT * INTO saved FROM public.buildings WHERE id=legacy_b;
  finance:=jsonb_build_object('baseOpening',5000,'reserve',300,'expenses',10000,'exceptional',8000,'startMonth',start_m,'openingAlreadyIncluded',NULL,'expected',private.building_financial_snapshot(saved));
  denied:=false; BEGIN PERFORM public.save_building_management(legacy_b,details,finance); EXCEPTION WHEN others THEN denied:=true; END;
  IF NOT denied THEN RAISE EXCEPTION 'Unknown legacy opening accepted without inclusion choice'; END IF;
  result:=public.save_building_management(legacy_b,details,finance||'{"openingAlreadyIncluded":true}');
  IF (result->>'balance')::numeric<>3000 THEN RAISE EXCEPTION 'Already included legacy opening was added twice'; END IF;
  UPDATE public.profiles SET building_id=legacy_add_b WHERE id=manager;
  SELECT * INTO saved FROM public.buildings WHERE id=legacy_add_b;
  finance:=finance||jsonb_build_object('expenses',0,'exceptional',0,'openingAlreadyIncluded',false,'expected',private.building_financial_snapshot(saved));
  result:=public.save_building_management(legacy_add_b,details,finance);
  IF (result->>'balance')::numeric<>5100 THEN RAISE EXCEPTION 'Legacy add-opening choice did not add the amount'; END IF;
  PERFORM public.clear_building_data(legacy_add_b,'reset','تصفير سجلات أرصدة موحدة');
  SELECT * INTO saved FROM public.buildings WHERE id=legacy_add_b;
  finance:=jsonb_build_object('baseOpening',0,'reserve',1000,'expenses',10000,'exceptional',8000,'startMonth',start_m,'openingAlreadyIncluded',NULL,'expected',private.building_financial_snapshot(saved));
  result:=public.save_building_management(legacy_add_b,details,finance);
  IF (result->>'balance')::numeric<>-2000 OR (result->>'opening_balance')::numeric<>-2000 OR (result->>'reserve_fund')::numeric<>1000 THEN RAISE EXCEPTION 'Unified post-reset deficit rejected or reserve added to cash'; END IF;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',newcomer)::text,true);
  finance:=jsonb_build_object('baseOpening',1000,'reserve',200,'expenses',50,'exceptional',20,'startMonth',start_m,'openingAlreadyIncluded',NULL);
  result:=public.create_manager_building_with_finances(jsonb_build_object('name','إنشاء ذري','totalUnits',1,'totalFloors',1,'monthlyTarget',100,'reserveFund',200),finance);
  created_id:=(result->>'id')::uuid;
  IF (result->>'balance')::numeric<>970 OR (result->>'reserve_fund')::numeric<>200 OR (SELECT count(*) FROM public.apartments WHERE building_id=created_id)<>1 THEN RAISE EXCEPTION 'Unified create failed or duplicated units: %',result; END IF;
  IF EXISTS(SELECT FROM public.payments WHERE building_id=created_id) THEN RAISE EXCEPTION 'Opening balance was recorded as a receipt'; END IF;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',failed_newcomer)::text,true);
  SELECT count(*) INTO building_count FROM public.buildings;
  denied:=false;
  BEGIN PERFORM public.create_manager_building_with_finances(jsonb_build_object('name','إنشاء مرفوض','totalUnits',1,'totalFloors',1,'monthlyTarget',100),finance||'{"baseOpening":-1}'); EXCEPTION WHEN others THEN denied:=true; END;
  IF NOT denied OR (SELECT building_id FROM public.profiles WHERE id=failed_newcomer) IS NOT NULL OR (SELECT count(*) FROM public.buildings)<>building_count THEN RAISE EXCEPTION 'Failed create left a partial building or membership'; END IF;
  RAISE EXCEPTION SQLSTATE 'Z0001' USING MESSAGE='unified financial save passed';
 EXCEPTION WHEN SQLSTATE 'Z0001' THEN NULL;
 END;
 IF EXISTS(SELECT FROM public.buildings WHERE id IN(b,other_b,legacy_b,legacy_add_b,created_id)) THEN RAISE EXCEPTION 'Fixture rollback failed'; END IF;
END $test$;
